import { describe, it, expect } from "bun:test";
import fs from "node:fs/promises";
import os from "node:os";
import path from "node:path";
import {
  splitRouteBlocks,
  detectRouteOwner,
  mergeRouteFile,
  stripOwnerBlocks,
  writeRouteFileAtomically,
} from "./route-merge.js";
import { generateCaddyfileSnippet } from "./generator.js";

const DEPLOY_PREFIX = "proj1-development";

describe("route-merge: splitRouteBlocks", () => {
  it("разбирает файл на блоки с доменами и upstream", () => {
    const content = [
      "# Auto-generated by Pegas for project: mixed-app [development]",
      "# header comment",
      "",
      "web.mixed-app.localhost {",
      "    reverse_proxy host.docker.internal:3100",
      "}",
      "",
      "worker.mixed-app.localhost {",
      "    reverse_proxy proj1-development-worker:3200",
      "}",
      "",
    ].join("\n");
    const blocks = splitRouteBlocks(content);
    expect(blocks.length).toBe(2);
    expect(blocks[0].domains).toEqual(["web.mixed-app.localhost"]);
    expect(blocks[0].upstream).toBe("host.docker.internal:3100");
    expect(blocks[1].upstream).toBe("proj1-development-worker:3200");
  });

  it("www-редирект считается блоком без reverse_proxy (upstream null)", () => {
    const content = "www.example.com {\n    redir https://example.com{uri} permanent\n}\n";
    const blocks = splitRouteBlocks(content);
    expect(blocks.length).toBe(1);
    expect(blocks[0].upstream).toBeNull();
  });
});

describe("route-merge: detectRouteOwner", () => {
  const mk = (upstream: string | null) => ({
    header: "d.com", body: upstream ? `reverse_proxy ${upstream}` : "", raw: "",
    domains: ["d.com"], upstream,
  });

  it("host.docker.internal — connect; scoped — deploy; прочее — unknown", () => {
    expect(detectRouteOwner(mk("host.docker.internal:3100"), DEPLOY_PREFIX)).toBe("connect");
    expect(detectRouteOwner(mk(`${DEPLOY_PREFIX}-worker:3200`), DEPLOY_PREFIX)).toBe("deploy");
    expect(detectRouteOwner(mk("other-host:3000"), DEPLOY_PREFIX)).toBe("unknown");
    expect(detectRouteOwner(mk(null), DEPLOY_PREFIX)).toBe("unknown");
  });

  it("чужой scoped-префикс (другой checkout) — unknown, не deploy", () => {
    expect(detectRouteOwner(mk("proj2-development-worker:3200"), DEPLOY_PREFIX)).toBe("unknown");
  });
});

describe("route-merge: mergeRouteFile (issue #24)", () => {
  const connectSnippet = generateCaddyfileSnippet({
    domain: "web.mixed-app.localhost",
    upstream: "host.docker.internal:3100",
  });
  const deploySnippet = generateCaddyfileSnippet({
    domain: "worker.mixed-app.localhost",
    upstream: `${DEPLOY_PREFIX}-worker:3200`,
  });

  const deployFile = [
    "# Auto-generated by Pegas for project: mixed-app [development]",
    "# Do not edit manually; update pegas.json instead.",
    "",
    deploySnippet.trimEnd(),
  ].join("\n") + "\n";

  it("connect сохраняет deploy-блоки и перезаписывает только свои", () => {
    const merged = mergeRouteFile(deployFile, ["# hdr"], "connect", DEPLOY_PREFIX, [connectSnippet]);
    expect(merged.content).toContain("web.mixed-app.localhost");
    expect(merged.content).toContain("host.docker.internal:3100");
    expect(merged.content).toContain("worker.mixed-app.localhost");
    expect(merged.content).toContain(`${DEPLOY_PREFIX}-worker:3200`);
    expect(merged.keptOther).toBe(1);
  });

  it("deploy сохраняет connect-блоки и перезаписывает только свои", () => {
    const connectFile = [
      "# Auto-generated by Pegas for project: mixed-app [development]",
      "# Proxies to native dev servers on the host via host.docker.internal",
      "",
      connectSnippet.trimEnd(),
    ].join("\n") + "\n";
    const merged = mergeRouteFile(connectFile, ["# hdr"], "deploy", DEPLOY_PREFIX, [deploySnippet]);
    expect(merged.content).toContain("host.docker.internal:3100");
    expect(merged.content).toContain(`${DEPLOY_PREFIX}-worker:3200`);
    expect(merged.keptOther).toBe(1);
  });

  it("свежие сниппеты заменяют свои старые блоки (без дублей)", () => {
    // connect-файл уже содержит блок web; connect пишет его заново — блок один.
    const connectFile = connectSnippet;
    const merged = mergeRouteFile(connectFile, ["# hdr"], "connect", DEPLOY_PREFIX, [connectSnippet]);
    expect(merged.content!.split("web.mixed-app.localhost {").length - 1).toBe(1);
    expect(merged.keptOther).toBe(0);
  });

  it("пустые сниппеты + нет чужих блоков => файл удаляется (content null)", () => {
    const merged = mergeRouteFile(connectSnippet, ["# hdr"], "connect", DEPLOY_PREFIX, []);
    expect(merged.content).toBeNull();
  });

  it("файл отсутствует: пишет только свои сниппеты", () => {
    const merged = mergeRouteFile(null, ["# hdr"], "connect", DEPLOY_PREFIX, [connectSnippet]);
    expect(merged.content).toContain("web.mixed-app.localhost");
    expect(merged.keptOther).toBe(0);
  });

  it("внешний (unknown) блок сохраняется дословно", () => {
    const foreign = "legacy.example.com {\n    reverse_proxy legacy-host:8080\n}";
    const merged = mergeRouteFile(foreign, ["# hdr"], "connect", DEPLOY_PREFIX, [connectSnippet]);
    expect(merged.content).toContain("legacy-host:8080");
    expect(merged.keptOther).toBe(1);
    expect(merged.removedDomains).toContain("legacy.example.com");
  });
});

describe("route-merge: stripOwnerBlocks (disconnect/down)", () => {
  const mixed = [
    "web.mixed-app.localhost {",
    "    reverse_proxy host.docker.internal:3100",
    "}",
    "",
    "worker.mixed-app.localhost {",
    "    reverse_proxy proj1-development-worker:3200",
    "}",
  ].join("\n");

  it("disconnect (owner connect) снимает только host-блоки", () => {
    const res = stripOwnerBlocks(mixed, "connect", DEPLOY_PREFIX);
    expect(res.content).toContain("proj1-development-worker:3200");
    expect(res.content).not.toContain("host.docker.internal");
    expect(res.removedDomains).toEqual(["web.mixed-app.localhost"]);
  });

  it("down (owner deploy) снимает только scoped-блоки", () => {
    const res = stripOwnerBlocks(mixed, "deploy", DEPLOY_PREFIX);
    expect(res.content).toContain("host.docker.internal:3100");
    expect(res.content).not.toContain("proj1-development-worker");
    expect(res.removedDomains).toEqual(["worker.mixed-app.localhost"]);
  });

  it("все блоки сняты => content null (файл удалить)", () => {
    const onlyConnect = "web.mixed-app.localhost {\n    reverse_proxy host.docker.internal:3100\n}";
    expect(stripOwnerBlocks(onlyConnect, "connect", DEPLOY_PREFIX).content).toBeNull();
  });

  it("файла нет => тихо", () => {
    const res = stripOwnerBlocks(null, "connect", DEPLOY_PREFIX);
    expect(res.content).toBeNull();
    expect(res.removedDomains).toEqual([]);
  });
});

describe("route-merge: writeRouteFileAtomically", () => {
  it("создаёт каталог и пишет файл атомарно, без .tmp-остатков", async () => {
    const dir = await fs.mkdtemp(path.join(os.tmpdir(), "pegas-merge-"));
    const file = path.join(dir, "conf.d", "proj.caddy");
    await writeRouteFileAtomically(file, "a.com {\n    reverse_proxy b:80\n}\n");
    expect(await fs.readFile(file, "utf-8")).toContain("a.com");
    const leftovers = (await fs.readdir(path.dirname(file))).filter((f) => f.endsWith(".tmp"));
    expect(leftovers).toEqual([]);
    await fs.rm(dir, { recursive: true, force: true });
  });
});
